CREATE TABLE `game` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `date` varchar(755) DEFAULT NULL,
  `event_name` varchar(755) DEFAULT NULL,
  `image` longblob,
  `theatre_number` varchar(755) DEFAULT NULL,
  `time` varchar(755) DEFAULT NULL,
  `type` varchar(755) DEFAULT NULL,
  `venue` varchar(755) DEFAULT NULL,
  `game_name` varchar(755) DEFAULT NULL,
  `instrcutions` varchar(755) DEFAULT NULL,
  `price_per_hour` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
