CREATE TABLE `movie` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `description` varchar(755) DEFAULT NULL,
  `duration` varchar(255) DEFAULT NULL,
  `format` varchar(755) DEFAULT NULL,
  `genre` varchar(755) DEFAULT NULL,
  `image` longblob,
  `language` varchar(755) DEFAULT NULL,
  `number_of_seat` bigint DEFAULT NULL,
  `price` varchar(755) DEFAULT NULL,
  `release_date` varchar(755) DEFAULT NULL,
  `show1` varchar(255) DEFAULT NULL,
  `show2` varchar(755) DEFAULT NULL,
  `show3` varchar(755) DEFAULT NULL,
  `show4` varchar(755) DEFAULT NULL,
  `show5` varchar(755) DEFAULT NULL,
  `status` varchar(755) DEFAULT NULL,
  `title` varchar(755) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
